input.command:
mkdir -p src && cat > Cargo.toml <<'E'
[package]
name = "word-frequency"
version = "0.1.0"
edition = "2021"
E
cat > src/main.rs <<'E'
use std::collections::HashMap;
use std::io::{self, Write};
use std::{env, fs, process};

fn main() {
    let Some(path) = env::args_os().nth(1) else {
        eprintln!("usage: word-frequency <file>");
        process::exit(2);
    };
    let data = match fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error reading file: {e}");
            process::exit(1);
        }
    };

    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in data
        .split(|b| !b.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        *counts.entry(word.to_ascii_lowercase()).or_insert(0) += 1;
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let mut out = io::BufWriter::new(io::stdout().lock());
    for (word, count) in entries.into_iter().take(10) {
        let _ = out.write_all(&word);
        let _ = writeln!(out, " {count}");
    }
    let _ = out.flush();
}
E
